import { FrameworkErrorCode } from "@mit-sdg/sync-engine/boundary";
function isPublicErrorCategory(value) {
    return (value === "INVALID_REQUEST" ||
        value === "UNAUTHORIZED" ||
        value === "FORBIDDEN" ||
        value === "NOT_FOUND" ||
        value === "CONFLICT");
}
export function registeredPublicCategoryOf(code, categories) {
    if (categories === undefined || !Object.hasOwn(categories, code))
        return "INTERNAL_ERROR";
    const category = categories[code];
    return isPublicErrorCategory(category) ? category : "INTERNAL_ERROR";
}
export function publicFrameworkCategoryOf(code) {
    switch (code) {
        case FrameworkErrorCode.INVALID_INPUT:
            return "INVALID_REQUEST";
        case FrameworkErrorCode.NOT_FOUND:
            return "NOT_FOUND";
        default:
            return "INTERNAL_ERROR";
    }
}
export function publicErrorStatus(category) {
    switch (category) {
        case "INVALID_REQUEST":
            return 400;
        case "UNAUTHORIZED":
            return 401;
        case "FORBIDDEN":
            return 403;
        case "NOT_FOUND":
            return 404;
        case "CONFLICT":
            return 409;
        case "INTERNAL_ERROR":
            return 500;
        default:
            return 500;
    }
}
export function projectHttpPublicErrors(wire, policy) {
    const categories = policy.publicErrors;
    return {
        endpoints: wire.endpoints.map((endpoint) => {
            const errors = new Set();
            let admissionError = endpoint.inputAdmissionError !== false;
            for (const code of endpoint.errors) {
                if (code === FrameworkErrorCode.INVALID_INPUT && admissionError) {
                    errors.add(publicFrameworkCategoryOf(code));
                    admissionError = false;
                    continue;
                }
                errors.add(registeredPublicCategoryOf(code, categories));
            }
            if (endpoint.openError)
                errors.add("INTERNAL_ERROR");
            return { ...endpoint, errors: [...errors].sort(), openError: false };
        }),
        appWide: [
            ...new Set(wire.appWide.map((code) => registeredPublicCategoryOf(code, categories))),
        ].sort(),
    };
}
